// Builds the Block Kit card. Every button's value is only the row id: the text lives in the table.
const s = $('Ask settings').first().json;
const kinds = $('Kinds').first().json.kinds;
const req = $('Loop over requests').first().json;
const r = $input.first().json;
const k = kinds[r.kind] || { label: r.kind, type: 'approval' };
const id = String(r.id);
const pre = k.value_prefix || '';
const name = req.link ? `<${req.link}|${r.item_label}>` : r.item_label;
const plain = t => ({ type: 'plain_text', text: t });
const btn = (text, action, extra = {}) => ({ type: 'button', text: plain(text), action_id: 'approval_' + action, value: id, ...extra });

const blocks = [{ type: 'header', text: plain((k.type === 'approval' ? `${k.label} to review` : k.label).slice(0, 150)) }];
const main = k.type !== 'approval' ? `*${name}*\n${r.context}`
  : r.current_value ? `*${name}*\n*Before*\n${r.current_value}\n*After*\n${r.proposed_value}`
  : `*${name}*\n${r.proposed_value}`;
const section = { type: 'section', text: { type: 'mrkdwn', text: main.slice(0, 3000) } };
const image = req.image_url ? { type: 'image', image_url: req.image_url, alt_text: r.item_label.slice(0, 2000),
  ...(req.image_title ? { title: plain(String(req.image_title).slice(0, 2000)) } : {}) } : null;
if (image && !k.large_image) section.accessory = image;
blocks.push(section);

// The fact line sits under what it describes: the length of the proposed text, or the alert's numbers.
const facts = (k.type === 'approval'
  ? [`${r.proposed_value.length}${r.max_length ? ' of ' + r.max_length : ''} characters`, r.context]
  : k.type === 'alert' ? [r.current_value ? `Now ${pre}${r.current_value}` : '', r.proposed_value ? `${k.action.text} sets it to ${pre}${r.proposed_value}` : ''] : []).filter(Boolean);
if (facts.length) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: facts.join(' · ') }] });
if (image && k.large_image) blocks.push(image);

// details: { label: value } from the caller. Short values sit side by side; long ones get their own line.
const details = Object.entries(req.details || {}).filter(([, v]) => v !== '' && v != null);
const short = details.filter(([, v]) => String(v).length <= 60);
if (short.length) blocks.push({ type: 'section', fields: short.slice(0, 10).map(([l, v]) => ({ type: 'mrkdwn', text: `*${l}*\n${v}` })) });
for (const [l, v] of details.filter(([, v]) => String(v).length > 60))
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${l}*\n${v}`.slice(0, 3000) } });

if (k.hint) blocks.push({ type: 'context', block_id: 'approval_hint', elements: [{ type: 'mrkdwn', text: k.hint }] });

const hours = h => h < 24 ? `${h} hour${h > 1 ? 's' : ''}` : h % 168 === 0 ? `${h / 168} week${h > 168 ? 's' : ''}` : `${h / 24} day${h > 24 ? 's' : ''}`;
let elements;
if (k.type === 'alert') elements = [
  btn(k.action.text, 'action', { style: 'primary', ...(k.action.confirm ? { confirm: {
    title: plain(k.action.text + '?'), text: { type: 'mrkdwn', text: k.action.confirm }, confirm: plain('Yes'), deny: plain('Cancel') } } : {}) }),
  { type: 'static_select', action_id: 'approval_snooze', placeholder: plain('Snooze'),
    options: (k.snooze_hours || [24]).map(h => ({ text: plain(hours(h)), value: id + '|' + h })) },
  btn('Ignore', 'ignore'),
];
else if (k.type === 'route') elements = [...k.routes.map(x => btn(x.text, 'route_' + x.id)), btn('Ignore', 'ignore')];
else elements = [btn('Approve', 'approve', { style: 'primary' }), btn('Edit', 'edit'), btn('Reject', 'reject', { style: 'danger' })];
if (s.page_button) elements.push(btn('Open in page', 'page'));
blocks.push({ type: 'actions', block_id: 'approval_actions', elements });

return [{ json: { row_id: r.id, channel: s.slack_channel, text: `${k.label}: ${r.item_label}`.slice(0, 300), blocks } }];

// What the caller gets back, straight away.
// The loop runs these nodes once per request, so read every run.
const run = n => { const out = []; for (let i = 0; i < 1000; i++) { let r; try { r = $(n).all(0, i); } catch (e) { break; } if (!r.length) break; out.push(...r.map(x => x.json)); } return out; };
return [{ json: {
  asked: run('Save channel and ts').map(r => ({ row_id: r.id, status: 'pending', channel: r.channel, ts: r.ts })),
  skipped: run('Skip it').length,
  failed: run('Mark failed').map(r => ({ row_id: r.id, reason: r.reason })),
} }];

// Reads the raw body first: Slack signs the exact bytes it sent. (A Set node before this would drop them.)
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
let p = {};
try { p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' '))); } catch (e) {}
const c = {
  base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'] || '',
  fresh: Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) <= 300,
  retry: !!h['x-slack-retry-num'], type: p.type || '', app_id: p.api_app_id || '', team_id: p.team?.id || p.user?.team_id || '',
  user_id: p.user?.id || '', response_url: p.response_url || '', trigger_id: p.trigger_id || '',
};
if (p.type === 'view_submission') {
  const m = JSON.parse(p.view.private_metadata || '{}');
  const v = p.view.state.values;
  if (p.view.callback_id === 'approval_edit')
    return [{ json: { ...c, action: 'edit_submit', row_id: Number(m.row_id), value: (v.value?.value?.value || '').trim() } }];
  return [{ json: { ...c, action: 'reject_submit', row_id: Number(m.row_id),
    reason: [v.reason?.reason?.selected_option?.value, (v.note?.note?.value || '').trim()].filter(Boolean).join(': ') } }];
}
const a = p.actions?.[0] || {};
const action = String(a.action_id || '').replace(/^approval_/, '');
if (action === 'snooze') {
  const [row, hours] = String(a.selected_option?.value || '').split('|');
  return [{ json: { ...c, action, row_id: Number(row), snooze_hours: Number(hours) } }];
}
return [{ json: { ...c, action, row_id: Number(a.value) || 0 } }];

// Validates a modal submission, so Slack can show the error under the field.
const c = $('Sign the request').first().json;
const row = $input.first().json;
const found = !!row.id;
let errors = null;
if (found && c.action === 'edit_submit') {
  const v = c.value, max = Number(row.max_length) || 0;
  const must = String(row.must_include || '').split(',').map(w => w.trim()).filter(Boolean);
  const missing = must.filter(w => !v.toLowerCase().includes(w.toLowerCase()));
  if (!v) errors = { value: 'Enter a value, or close this and press Reject.' };
  else if (max && v.length > max) errors = { value: `That's ${v.length} characters. The limit is ${max}.` };
  else if (missing.length) errors = { value: `Keep ${missing.join(', ')} in it.` };
}
const exp = Math.floor(Date.now() / 1000) + 3600 * (Number(c.link_hours) || 8);
const { base, expected, sig, ...click } = c;
return [{ json: { ...click, found, errors, exp, row: found ? row : null } }];

