// Turns the decision into a status, the value to apply and the line the card will show.
const t = $('Apply the change').first().json;
const s = $('Apply settings').first().json;
const row = $input.first().json;
if (!row.id) throw new Error('No approval row ' + t.row_id);
const d = String(t.decision);
const button = (JSON.parse(row.card || '[]').find(b => b.type === 'actions')?.elements || [])
  .find(e => e.action_id === 'approval_' + d)?.text?.text;
const edited = d === 'edit' && t.final_value !== row.proposed_value;
const plans = {
  approve: { status: 'approved', changes: true, value: row.proposed_value, word: 'Approved', icon: ':white_check_mark:', label: 'Approved' },
  edit: { status: edited ? 'edited' : 'approved', changes: true, value: t.final_value, word: 'Approved', icon: ':white_check_mark:', label: edited ? 'Edited and approved' : 'Approved' },
  action: { status: 'approved', changes: true, value: row.proposed_value, word: 'Done', icon: ':white_check_mark:', label: button || 'Done' },
  reject: { status: 'rejected', changes: false, value: '', word: 'Rejected', icon: ':no_entry:', label: 'Rejected' },
  ignore: { status: 'acknowledged', changes: false, value: '', word: 'Ignored', icon: ':heavy_minus_sign:', label: 'Ignored' },
  snooze: { status: 'snoozed', changes: false, value: '', word: 'Snoozed', icon: ':zzz:', label: 'Snoozed' },
};
const plan = plans[d] || (d.startsWith('route_')
  ? { status: 'routed', changes: false, value: d.slice(6), word: 'Sent', icon: ':arrow_right:', label: 'Sent to ' + (button || d.slice(6)) } : null);
if (!plan) throw new Error('Unknown decision ' + d);
const fmt = (date, o) => date.toLocaleString('en-AU', { timeZone: s.timezone, ...o });
const snooze_until = d === 'snooze' ? new Date(Date.now() + 3600e3 * (Number(t.snooze_hours) || 24)) : null;
const who = t.via === 'page' ? `<@${t.user_id}> on the page` : `<@${t.user_id}>`;
let note = `${plan.icon} ${plan.label} by ${who} · ${fmt(new Date(), { hour: 'numeric', minute: '2-digit' })}`;
if (snooze_until) note = `${plan.icon} Snoozed by ${who} until ${fmt(snooze_until, { weekday: 'short', hour: 'numeric', minute: '2-digit' })}`;
if (t.reason) note += `\n>${t.reason}`;
return [{ json: { ...row, decision: d, ...plan, final_value: plan.value, reason: t.reason || '', user_id: t.user_id,
  note, snooze_until: snooze_until ? snooze_until.toISOString() : null, decided_at: new Date().toISOString() } }];

// What your apply workflow receives, for every decision on its kind.
const p = $input.first().json;
return [{ json: { row_id: p.id, kind: p.kind, item_id: p.item_id, item_label: p.item_label, decision: p.decision,
  final_value: p.final_value, reason: p.reason, decided_by: p.user_id, context: p.context } }];

