// Gathers the reason from whichever branch failed.
const j = $input.first().json;
const msgs = [j.error?.message || (typeof j.error === 'string' ? j.error : ''), ...(j.errors || []).map(e => e.message),
  ...((j.data?.productUpdate || j.data?.productVariantsBulkUpdate)?.userErrors || []).map(e => e.message)].filter(Boolean);
return [{ json: { error: msgs.join('; ') || 'unknown error' } }];

// A plain list of everything pending, with the buttons from each card.
const s = $('Page settings').first().json;
const q = s.query;
const rows = $input.all().map(i => i.json).filter(r => r.id);
const esc = t => String(t ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const md = t => esc(t).replace(/\*([^*\n]+)\*/g, '<b>$1</b>').replace(/&lt;(https?:[^|]+)\|([^&]+)&gt;/g, '<a href="$1">$2</a>').replace(/\n/g, '<br>');
const cards = rows.map(r => {
  const blocks = JSON.parse(r.card || '[]');
  const head = blocks.find(b => b.type === 'header')?.text?.text || r.kind;
  const body = blocks.find(b => b.type === 'section')?.text?.text || esc(r.item_label);
  const note = blocks.find(b => b.type === 'context')?.elements?.[0]?.text || '';
  const buttons = (blocks.find(b => b.type === 'actions')?.elements || [])
    .filter(e => e.type === 'button' && !['approval_edit', 'approval_page'].includes(e.action_id))
    .map(e => `<button class="${e.style || ''}" data-d="${esc(e.action_id.replace('approval_', ''))}">${esc(e.text.text)}</button>`).join('');
  const asked = new Date(r.requested_at).toLocaleString('en-AU', { timeZone: s.timezone, day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' });
  return `<section class="card" data-id="${r.id}"><div class="kind">${esc(head)} · asked ${esc(asked)}</div><div class="body">${md(body)}</div>`
    + `<div class="note">${md(note)}</div><div class="buttons">${buttons}</div><div class="done"></div></section>`;
}).join('');
const auth = JSON.stringify({ u: q.u, exp: q.exp, sig: q.sig });
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Approvals</title><style>
body{margin:0;background:#f8f8f8;color:#1d1c1d;font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif}
main{max-width:860px;margin:0 auto;padding:24px 16px}h1{font-size:22px;margin:0 0 16px}
.card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:14px 16px;margin:0 0 12px}
.kind{font-size:12px;color:#616061;text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px}.note{color:#616061;font-size:13px;margin-top:6px}
button{font:inherit;font-weight:600;border:1px solid #bbb;background:#fff;border-radius:6px;padding:5px 14px;margin:10px 8px 0 0;cursor:pointer}
button.primary{background:#007a5a;border-color:#007a5a;color:#fff}button.danger{color:#e01e5a;border-color:#e01e5a}button:disabled{opacity:.5}
.done{margin-top:8px;font-weight:600}</style></head><body><main>
<h1>${rows.length} waiting for a decision</h1>${cards || '<p>Nothing waiting. Nice.</p>'}</main>
<script>
const AUTH = ${auth}, DECIDE = ${JSON.stringify(s.decide_url)};
document.querySelectorAll('.card button').forEach(b => b.addEventListener('click', async () => {
  const card = b.closest('.card'), out = card.querySelector('.done');
  card.querySelectorAll('button').forEach(x => x.disabled = true);
  out.textContent = 'Working...';
  try {
    const r = await fetch(DECIDE, { method: 'POST', body: new URLSearchParams({ ...AUTH, row_id: card.dataset.id, decision: b.dataset.d }) });
    const j = await r.json();
    out.textContent = j.message;
    if (!j.ok) card.querySelectorAll('button').forEach(x => x.disabled = false);
  } catch (e) { out.textContent = 'Could not reach n8n. Try again.'; card.querySelectorAll('button').forEach(x => x.disabled = false); }
}));
</script></body></html>`;
return [{ json: { html } }];

// One nudge, then expiry; snoozed alerts wake up; a row stuck in processing for an hour goes back to pending.
const s = $('Remind settings').first().json;
const now = Date.now(), hour = 3600e3;
const out = [];
for (const { json: r } of $input.all()) {
  const age = (now - new Date(r.requested_at).getTime()) / hour;
  let todo = null;
  if (r.status === 'snoozed') { if (r.snooze_until && new Date(r.snooze_until).getTime() <= now) todo = 'wake'; }
  else if (age >= 24 * s.expire_after_days) todo = 'expire';
  else if (r.status === 'processing') { if ((now - new Date(r.updatedAt).getTime()) / hour >= 1) todo = 'unstick'; }
  else if (age >= s.remind_after_hours && !r.reminded_at) todo = 'remind';
  if (todo && r.ts) out.push({ json: { ...r, todo, age_hours: Math.round(age) } });
}
return out;

// Raw body first (Shopify signs the exact bytes), then one change per thing a card can be about.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
let p = {};
try { p = JSON.parse(raw); } catch (e) {}
const changes = [{ item_id: p.admin_graphql_api_id, kind: 'product_title', new_value: p.title, source: 'Shopify' },
  ...(p.variants || []).map(v => ({ item_id: v.admin_graphql_api_id, kind: 'price_alert', new_value: v.price, source: 'Shopify' }))];
return [{ json: { raw, expected: h['x-shopify-hmac-sha256'] || '', changes: changes.filter(c => c.item_id) } }];

// Keeps open rows whose current value no longer matches the source.
// A change that matches what was proposed or approved is this workflow's own write landing, so it's skipped.
const changes = $('Sync settings').all().map(i => i.json);
const open = $('Sync settings').first().json.statuses_to_close;
const same = (a, b) => (isFinite(a) && isFinite(b) && a !== '' && b !== '') ? Number(a) === Number(b) : String(a) === String(b);
const out = [], seen = new Set();
for (const { json: r } of $input.all()) {
  const c = changes.find(c => c.item_id === r.item_id && (!c.kind || c.kind === r.kind));
  if (!c || !open.includes(r.status) || seen.has(r.id)) continue;
  if ([r.current_value, r.proposed_value, r.final_value].some(v => v != null && v !== '' && same(v, c.new_value))) continue;
  seen.add(r.id);
  out.push({ json: { ...r, new_value: String(c.new_value ?? ''), source: c.source || 'the source' } });
}
return out;
